(91, 62, 'Bùi Thanh Quỳnh', '0333279763', 'TP. Hồ Chí Minh', 'TP. Thủ Đức', 'Phường Thảo Điền', '110 Xuân Thủy', 1, '2026-08-02 10:00:00'),
(92, 62, 'Bùi Thanh Quỳnh', '0333279763', 'TP. Hồ Chí Minh', 'TP. Thủ Đức', 'Phường Thảo Điền', '191 Quốc Hương', 0, '2026-08-02 10:00:00'),
