INSERT INTO categories (id, name, slug, description, sort_order) VALUES
(1, 'Cà phê rang', 'ca-phe-rang', 'Hạt cà phê đặc sản Việt Nam rang nhỏ mẻ mỗi tuần theo từng vùng trồng.', 1),
(2, 'Drip bag và hòa tan', 'drip-bag-hoa-tan', 'Cà phê túi lọc pha rót và hòa tan sấy lạnh giữ nguyên hương hạt rang mộc.', 2),
(3, 'Dụng cụ pha chế', 'dung-cu-pha-che', 'Phễu lọc, bình pha, ấm rót và cân điện tử cho quầy pha cà phê tại nhà.', 3),
(4, 'Ly và cốc gốm', 'ly-coc-gom', 'Cốc gốm thủ công và ly thủy tinh giữ nhiệt, tối ưu cảm nhận hương vị.', 4),
(5, 'Phụ kiện', 'phu-kien', 'Giấy lọc, máy xay tay, hộp kín khí và dụng cụ vệ sinh thiết yếu.', 5),
(6, 'Quà tặng và combo', 'qua-tang-combo', 'Hộp thử vị và bộ pha khởi đầu đóng gói chỉn chu để biếu tặng.', 6);
INSERT INTO products (id, category_id, name, slug, short_description, description, origin, roast_level, is_active, is_featured, created_at) VALUES
(1, 1, 'Arabica Cầu Đất Washed', 'arabica-cau-dat-washed', 'Hương hoa trắng, cam vàng và hậu ngọt mật mía từ độ cao 1.550m Đà Lạt.', 'Thu hoạch chín mọng 100% tại vùng Cầu Đất (1.550m), sơ chế ướt lên men 18 giờ và phơi giàn nắng tự nhiên. Rang sáng vừa giúp giữ trọn độ chua thanh của cam vàng, thoảng hương hoa nhài và hậu vị ngọt kéo dài.\n\nGợi ý pha pour-over V60 tỉ lệ 1:15 (16g cà phê với 240ml nước 92°C), thời gian chiết xuất 2 phút 30 giây. Hợp uống nóng hoặc rót qua đá viên lớn.', 'Cầu Đất, Đà Lạt · 1.550m', 'light', 1, 1, '2026-07-04 10:00:00'),
(2, 1, 'Arabica Cầu Đất Honey', 'arabica-cau-dat-honey', 'Chua dịu kiểu mơ chín, vị ngọt caramel dày và hương trà đào rõ nét.', 'Giữ lại lớp thịt quả khi phơi trên giàn lưới trong 14 ngày tại Xuân Trường, Đà Lạt. Mức rang vừa mở ra cấu trúc vị tròn đầy, nổi bật nốt mơ chín, đường nâu và hậu vị sạch.\n\nPhù hợp cho cả pha giấy lọc lẫn pha máy espresso. Với Aeropress, dùng 18g cà phê xay trung bình, 220ml nước 90°C, ủ 90 giây rồi ép chậm.', 'Cầu Đất, Đà Lạt · 1.500m', 'medium', 1, 1, '2026-06-29 10:00:00'),
(3, 1, 'Robusta Buôn Ma Thuột Honey', 'robusta-buon-ma-thuot-honey', 'Đậm đà hương cacao đen, hạt dẻ rang và lớp crema dày mịn khi pha phin.', 'Fine Robusta trồng ở độ cao 750m tại Cư M\'gar, Đắk Lắk, chọn trái chín đỏ và sơ chế mật ong. Rang đậm vừa giúp giảm gắt, làm nổi vị sô-cô-la đen, hạt phỉ và hậu ngọt dịu không khét.\n\nDùng pha phin truyền thống: 25g cà phê xay vừa, châm 30ml nước 93°C ủ 45 giây rồi rót tiếp 55ml. Rất hợp kết hợp sữa đặc hoặc uống đen đá.', 'Buôn Ma Thuột · 750m', 'dark', 1, 1, '2026-06-08 10:00:00'),
(4, 1, 'Robusta Buôn Ma Thuột Natural', 'robusta-buon-ma-thuot-natural', 'Vị đậm chắc, mùi mít chín nhẹ, đường thắng và hạt điều rang bùi.', 'Phơi nguyên trái trên sân gạch dưới nắng Tây Nguyên suốt 18 ngày để đường tự nhiên thấm sâu vào nhân. Rang đậm có kiểm soát giữ thân vị dày, thơm nồng mùi đường nâu và hạt điều.\n\nThích hợp pha phin nhôm hoặc Moka Pot. Nếu pha Moka Pot 3 cup, dùng 18g cà phê xay mịn vừa và nước nóng 85°C ở khoang dưới để tránh đắng gắt.', 'Buôn Ma Thuột · 700m', 'dark', 1, 0, '2026-07-19 10:00:00'),
(5, 1, 'Arabica Khe Sanh Washed', 'arabica-khe-sanh-washed', 'Hương chanh dây, thảo mộc nhẹ và hậu vị trà xanh mát cổ từ Quảng Trị.', 'Trồng trên nền đất đỏ bazan vùng Hướng Hóa ở độ cao 700m, giống Catimor Khe Sanh mang cá tính chua tươi và mùi thảo mộc đặc trưng. Rang sáng để bộc lộ nốt chanh dây và vỏ bưởi.\n\nNgon nhất khi pha Cold Brew tỉ lệ 1:10 ủ lạnh 14 tiếng, hoặc pha V60 với nước 91°C để cảm nhận vị trà rõ rệt.', 'Khe Sanh, Quảng Trị · 700m', 'light', 1, 1, '2026-07-27 10:00:00'),
(6, 1, 'Arabica Khe Sanh Natural', 'arabica-khe-sanh-natural', 'Nốt dâu tằm, rượu vang đỏ nhẹ và vị ngọt mứt quả kéo dài.', 'Những mẻ trái chín cuối vụ tại Khe Sanh được phơi khô nguyên vỏ trên giàn cao giúp hạt mang hương quả mọng đậm và độ ngọt cao. Rang mức vừa để cân bằng giữa vị chua trái cây và cacao.\n\nKhuyên pha bằng phễu đáy phẳng Kalita tỉ lệ 1:15, nhiệt độ nước 90°C, chia 3 lần rót đều tay.', 'Khe Sanh, Quảng Trị · 750m', 'medium', 1, 0, '2026-07-18 10:00:00'),
(7, 1, 'Arabica Sơn La Washed', 'arabica-son-la-washed', 'Thơm táo xanh, hạnh nhân và vị ngọt sạch dễ uống mỗi sáng.', 'Hạt Arabica vùng Chiềng Ban, Mai Sơn (1.100m) sơ chế ướt bằng nguồn nước suối núi. Rang vừa sáng cho tách cà phê cân bằng, ít đắng, nổi mùi táo xanh và hạt hạnh nhân rang.\n\nHợp pha giấy lọc, French Press hoặc máy pha gia đình. Với French Press, dùng 20g cà phê xay thô với 300ml nước 92°C, ngâm 4 phút.', 'Sơn La · 1.100m', 'medium', 1, 1, '2026-07-04 10:00:00'),
(8, 1, 'Culi Sơn La Rang Vừa', 'culi-son-la-rang-vua', 'Hạt tròn đơn nhân cô đặc hương vị: sô-cô-la sữa, caramel và chút cam khô.', 'Tuyển lọc những hạt Peaberry (Culi) tròn đơn nhân từ vụ thu hoạch Sơn La, hàm lượng tinh dầu cao hơn hạt phẳng thông thường. Rang vừa giúp vị dày, thơm mùi bơ cacao và cam thảo.\n\nPha Espresso chiết xuất 18g lấy 36g trong 27 giây cho lớp crema mịn, uống cùng sữa tươi không đường rất hài hòa.', 'Sơn La · 1.150m', 'medium', 1, 0, '2026-07-28 10:00:00'),
(9, 1, 'Arabica Lâm Đồng Lạc Dương', 'arabica-lam-dong-lac-duong', 'Hương hoa cà phê, quýt chín và mật ong rừng từ vùng Langbiang.', 'Thu hái ở độ cao 1.600m dưới chân núi Langbiang, khí hậu lạnh quanh năm giúp trái chín chậm và tích đường cao. Rang sáng làm bật vị chua thanh kiểu quýt chín và hậu mật ong.\n\nKhuyến nghị pha V60 hoặc Chemex với tỉ lệ 1:16, nước 93°C, xay cỡ đường cát trung bình.', 'Lâm Đồng · 1.600m', 'light', 1, 0, '2026-06-20 10:00:00'),
(10, 1, 'Blend Sáng Tĩnh Lặng (70A/30R)', 'blend-sang-tinh-lang', 'Phối trộn 70% Arabica Cầu Đất và 30% Fine Robusta, thơm hạt rang, ít chua.', 'Công thức phối trộn quen thuộc của Nhà Rang dành cho người thích ly cà phê cân bằng: đủ thơm hương trái cây từ Arabica nhưng vẫn có độ đậm và hậu cacao của Robusta.\n\nĐa dụng cho cả pha máy Espresso, Moka Pot lẫn pha phin. Dùng 18g cho máy pha đôi, chiết xuất ở 92°C.', 'Cầu Đất & Buôn Ma Thuột', 'medium', 1, 1, '2026-07-28 10:00:00'),
(11, 1, 'Blend Phin Truyền Thống (40A/60R)', 'blend-phin-truyen-thong', 'Đậm vị cà phê sữa đá Sài Gòn: thơm sô-cô-la đắng, bơ lạc và hậu ngọt.', 'Kết hợp 60% Robusta Buôn Ma Thuột rang đậm cùng 40% Arabica Lâm Đồng rang vừa, không tẩm hương liệu hay bơ dầu. Cho nước cốt sánh, thơm sâu và không gắt cổ.\n\nPha phin 25g cà phê, rót 80ml nước sôi 94°C, thêm 25ml sữa đặc và đá bi để có ly nâu đá chuẩn vị.', 'Buôn Ma Thuột & Lâm Đồng', 'dark', 1, 0, '2026-06-21 10:00:00'),
(12, 1, 'Blend Espresso Nhà Rang', 'blend-espresso-nha-rang', 'Tối ưu cho máy pha gia đình: crema dày, vị caramel và hạnh nhân nướng.', 'Phối giữa Arabica Sơn La và Robusta chế biến ướt theo tỉ lệ 60/40, hồ sơ rang phát triển chậm giúp hạt ổn định áp suất chiết xuất. Khi pha với sữa tươi tạo vị ngọt béo tự nhiên.\n\nTỉ lệ khuyến nghị 1:2 (18g bột lấy 36g cốt) trong 26–30 giây ở 93°C.', 'Sơn La & Buôn Ma Thuột', 'medium', 1, 0, '2026-07-20 10:00:00'),
(13, 1, 'Typica Đà Lạt Lô Nhỏ', 'typica-da-lat-lo-nho', 'Hương trà ô long, đào trắng và đường phèn từ giống Typica cổ.', 'Mẻ nhỏ sản lượng hạn chế từ nông hộ tại Trạm Hành, Cầu Đất. Giống Typica hạt dài cho hương thơm tinh tế của hoa trắng, trà ô long và hậu vị ngọt thanh như đường phèn.\n\nChỉ rang mức sáng nhẹ. Pha V60 tỉ lệ 1:16, nước 92°C, dùng nước lọc mềm (TDS 50–80 ppm) để vị trà rõ nhất.', 'Cầu Đất, Đà Lạt · 1.600m', 'light', 1, 1, '2026-06-28 10:00:00'),
(14, 1, 'Cold Brew Blend Hạt Thô', 'cold-brew-blend-hat-tho', 'Phối trộn riêng để ủ lạnh: mát vị cam sấy, cacao nhẹ và gần như không đắng.', 'Xay sẵn cỡ thô đồng đều từ Arabica Khe Sanh và Cầu Đất rang vừa sáng, đóng túi van một chiều. Khi ngâm lạnh 14–16 giờ cho nước cốt trong, thơm vỏ cam sấy và hậu ngọt tự nhiên.\n\nTỉ lệ ủ gợi ý: 50g cà phê với 500ml nước mát, lọc qua giấy lọc để uống dần trong 4 ngày.', 'Khe Sanh & Cầu Đất', 'medium', 1, 0, '2026-06-13 10:00:00'),
(15, 2, 'Hộp 10 Gói Drip Arabica Cầu Đất', 'drip-arabica-cau-dat', '10 túi lọc tai treo 12g rang xay mộc, mở ra là pha được ly pour-over.', 'Mỗi gói chứa 12g Arabica Cầu Đất rang vừa xay đúng cỡ lọc, nạp khí nitơ để giữ hương thơm như mới xay. Không cần phễu hay cân, chỉ cần ly cao và ấm nước nóng.\n\nCách pha: xé miệng túi, gài hai tai lên miệng ly, rót 30ml nước 92°C ủ 30 giây, sau đó rót thêm 150ml làm 2 lần.', 'Cầu Đất, Đà Lạt · 1.550m', 'medium', 1, 1, '2026-06-28 10:00:00'),
(16, 2, 'Hộp 10 Gói Drip Robusta Đậm Đà', 'drip-robusta-dam-da', 'Túi lọc vị đậm kiểu cà phê phin, hợp mang đi làm hoặc đi công tác.', 'Sử dụng Fine Robusta Buôn Ma Thuột rang đậm vừa, đóng 14g mỗi túi cho tách cà phê dày vị cacao và hạt dẻ. Tiện lợi khi uống nóng hoặc pha ít nước để uống với đá.\n\nRót tổng cộng 120ml nước 93°C (nếu uống đá chỉ dùng 90ml), thời gian nhỏ giọt khoảng 2 phút.', 'Buôn Ma Thuột · 750m', 'dark', 1, 0, '2026-06-30 10:00:00'),
(17, 2, 'Hộp Drip Thử Vị 3 Vùng Trồng', 'drip-thu-vi-3-vung', '9 gói gồm Cầu Đất, Khe Sanh và Sơn La để nếm thử sự khác biệt từng vùng.', 'Bộ hộp gồm 3 gói Arabica Cầu Đất (chua thanh cam vàng), 3 gói Arabica Khe Sanh (hương chanh dây, thảo mộc) và 3 gói Arabica Sơn La (táo xanh, hạnh nhân). Kèm thẻ ghi chú nốt hương in giấy mỹ thuật.\n\nPhù hợp cho người mới tìm hiểu cà phê đặc sản muốn tự so sánh hương vị tại nhà.', 'Đà Lạt · Khe Sanh · Sơn La', 'light', 1, 0, '2026-07-11 10:00:00'),
(18, 2, 'Cà Phê Hòa Tan Sấy Lạnh Arabica', 'hoa-tan-say-lanh-arabica', 'Chiết xuất 100% Arabica Lâm Đồng sấy thăng hoa ở -40°C, tan nhanh cả nước lạnh.', 'Thay vì sấy phun nhiệt cao làm mất mùi, dịch chiết cà phê được đông lạnh sâu và thăng hoa chân không để giữ lại hương hoa quả và vị ngọt tự nhiên. Không đường, không chất độn.\n\nPha 1 gói 2.5g với 120ml nước nóng hoặc nước lọc lạnh, khuấy 5 giây là dùng được ngay.', 'Lâm Đồng · 1.500m', 'medium', 1, 0, '2026-06-26 10:00:00'),
(19, 2, 'Túi Ủ Lạnh Cold Brew Nhúng 6 Gói', 'tui-u-lanh-cold-brew-6-goi', 'Túi lọc vải không dệt chứa 35g cà phê xay thô, thả vào bình là xong.', 'Mỗi túi lọc thiết kế vừa cho 350–400ml nước lọc, giúp bạn làm cà phê ủ lạnh sạch bã mà không cần dụng cụ lọc riêng. Hạt Arabica Sơn La rang vừa cho vị êm, hương cacao sữa.\n\nNgâm túi trong ngăn mát tủ lạnh 12 đến 16 tiếng rồi vớt bỏ túi, bảo quản dùng trong 4 ngày.', 'Sơn La · 1.100m', 'medium', 1, 0, '2026-07-02 10:00:00'),
(20, 2, 'Cà Phê Hòa Tan Sấy Lạnh Vị Cacao', 'hoa-tan-say-lanh-cacao', 'Phối trộn cà phê sấy lạnh cùng bột cacao Đắk Lắk nguyên chất, không đường.', 'Tỉ lệ 75% tinh chất cà phê Robusta - Arabica sấy lạnh kết hợp 25% bột cacao lên men tự nhiên, mang lại mùi mocha dịu nhẹ mà không bị ngọt gắt.\n\nPha với 150ml sữa tươi ấm hoặc sữa hạt tạo nên ly mocha sáng nhanh gọn trong 1 phút.', 'Đắk Lắk & Lâm Đồng', 'dark', 1, 0, '2026-08-07 10:00:00'),
(21, 3, 'Phễu Lọc Gốm V60 Cỡ 02', 'pheu-loc-gom-v60-02', 'Phễu lọc gốm sứ tráng men giữ nhiệt ổn định, rãnh xoắn thoát nước đều.', 'Đúc từ đất sét trắng nung ở 1.250°C với các đường gân xoắn ốc bên trong giúp giấy lọc không bám sát thành phễu, giữ dòng chảy thông thoáng. Cỡ 02 pha thoải mái từ 1 đến 4 tách (15–35g cà phê).\n\nĐường kính miệng 11.5cm, cao 10cm, nặng 320g. Dùng chung với giấy lọc hình nón cỡ 02, vệ sinh được trong máy rửa chén.', NULL, NULL, 1, 1, '2026-07-12 10:00:00'),
(22, 3, 'Phễu Lọc Thủy Tinh Đáy Phẳng', 'pheu-loc-thuy-tinh-day-phang', 'Thủy tinh borosilicate chịu nhiệt, thiết kế 3 lỗ thoát giúp chiết xuất ngọt đều.', 'Phễu đáy phẳng giảm sai số khi rót nước, rất dễ làm quen cho người mới tập pour-over. Chất liệu thủy tinh borosilicate dày 2.5mm chịu sốc nhiệt từ -10°C đến 120°C.\n\nKích thước cỡ 185 (pha 18–30g cà phê), đế silicone rời chống trượt khi đặt lên bình server hoặc trực tiếp lên cốc.', NULL, NULL, 1, 0, '2026-07-16 10:00:00'),
(23, 3, 'Bình Server Thủy Tinh 600ml', 'binh-server-thuy-tinh-600ml', 'Bình đựng cà phê có vạch chia ml rõ nét, vòi rót chống nhỏ giọt.', 'Thân bình thổi từ thủy tinh chịu nhiệt nhẹ tay, có vạch chia từ 100ml đến 600ml dễ canh lượng nước chiết xuất. Nắp đậy có gioăng silicone giữ ấm lâu hơn.\n\nĐường kính miệng 8.2cm tương thích với hầu hết phễu V60 và phễu đáy phẳng. Không đun trực tiếp trên bếp gas.', NULL, NULL, 1, 0, '2026-07-24 10:00:00'),
(24, 3, 'Bình Pha Ép Aeropress Go', 'binh-pha-ep-aeropress-go', 'Dụng cụ pha ép khí nén gọn nhẹ, đóng trọn bộ trong chiếc cốc du lịch.', 'Chiết xuất cà phê sạch bã, đậm đà chỉ trong 2 phút nhờ áp suất tay kết hợp giấy lọc tròn. Toàn bộ thân piston, muỗng đong, que khuấy và hộp giấy lọc xếp gọn trong cốc 440ml có nắp silicone.\n\nChất liệu nhựa polypropylene không chứa BPA, chịu nhiệt tốt, dễ rửa chỉ bằng cách xả nước ấm.', NULL, NULL, 1, 1, '2026-07-31 10:00:00'),
(25, 3, 'Bình Pha French Press 600ml', 'binh-pha-french-press-600ml', 'Lưới lọc thép không gỉ 2 lớp cho tách cà phê dày vị, giữ trọn lớp dầu hạt.', 'Khung bảo vệ inox 304 mờ chắc chắn bọc quanh lõi thủy tinh borosilicate 600ml (pha 3–4 tách). Bộ lọc kép bằng lưới thép mắt mịn hạn chế tối đa cặn bột rơi vào ly.\n\nThích hợp pha cà phê xay thô, pha trà lá nguyên cánh hoặc đánh bọt sữa thủ công tại nhà.', NULL, NULL, 1, 0, '2026-08-08 10:00:00'),
(26, 3, 'Ấm Pha Moka Pot Nhôm 3 Cup', 'am-pha-moka-pot-3-cup', 'Ấm đun bếp kiểu Ý chiết xuất cà phê đậm sánh như espresso không cần máy.', 'Đúc từ hợp kim nhôm dẫn nhiệt nhanh, thiết kế thân 8 cạnh cổ điển giúp phân tán nhiệt đều. Dung tích 3 cup cho ra khoảng 130–150ml cốt cà phê đậm đà.\n\nTay cầm nhựa phenolic cách nhiệt, van an toàn bằng đồng. Dùng được trên bếp gas và bếp hồng ngoại (bếp từ cần thêm đĩa chuyển nhiệt).', NULL, NULL, 1, 0, '2026-07-23 10:00:00'),
(27, 3, 'Ấm Rót Cổ Ngỗng Inox 600ml', 'am-rot-co-ngong-600ml', 'Vòi cổ ngỗng đường kính 6mm kiểm soát dòng nước mảnh và thẳng đứng.', 'Thân ấm bằng thép không gỉ 304 phủ sơn tĩnh điện đen nhám, chống bám vân tay. Nắp ấm có lỗ cắm nhiệt kế tiện theo dõi nhiệt độ nước khi pha giấy lọc.\n\nDung tích sử dụng tối ưu 500–600ml, nặng 410g cân bằng tay cầm. Đáy phẳng đun được trên bếp từ và bếp gas lửa nhỏ.', NULL, NULL, 1, 1, '2026-06-18 10:00:00'),
(28, 3, 'Ấm Rót Điện Kiểm Soát Nhiệt 800ml', 'am-rot-dien-nhiet-800ml', 'Chỉnh chính xác từng độ từ 40°C đến 100°C, giữ ấm 60 phút, màn hình LED.', 'Công suất 1.200W đun sôi 600ml nước trong khoảng 3 phút, tích hợp đồng hồ bấm giờ chiết xuất ngay trên đế điện. Vòi cổ ngỗng cong mượt giúp dòng rót không bị đứt đoạn.\n\nPhù hợp cho người pha pour-over thường xuyên muốn kiểm soát ổn định nhiệt độ giữa các mẻ cà phê khác nhau.', NULL, NULL, 1, 0, '2026-07-11 10:00:00'),
(29, 3, 'Cân Điện Tử Pha Cà Phê Có Bấm Giờ', 'can-dien-tu-pha-ca-phe', 'Độ chia 0.1g, tải tối đa 2kg, sạc USB-C và có tấm lót silicone cách nhiệt.', 'Cảm biến phản hồi nhanh, hiển thị đồng thời trọng lượng và thời gian chiết xuất trên màn hình LED ẩn dưới mặt kính mờ. Tích hợp chế độ tự chạy đồng hồ khi phát hiện giọt nước đầu tiên.\n\nPin sạc 1.000mAh dùng khoảng 2 tháng mỗi lần sạc. Kích thước 13x15cm vừa vặn cả bình server lẫn tay pha espresso.', NULL, NULL, 1, 1, '2026-07-07 10:00:00'),
(30, 3, 'Phin Pha Cà Phê Inox 304 Đế Rời', 'phin-pha-inox-304', 'Phin inox dày 0.8mm khoan lỗ mịn bằng laser, nhỏ giọt đều trong 5 phút.', 'Gia công từ inox 304 an toàn thực phẩm, gài nén thiết kế vít vặn chắc chắn giúp ổn định độ nén bột. Miệng phin đường kính 7.5cm đặt vừa đa số cốc sứ và ly thủy tinh.\n\nDung tích 170ml pha chuẩn 20–25g bột cà phê. Đi kèm nắp đậy kiêm đĩa lót chống nhỏ giọt sau khi pha.', NULL, NULL, 1, 0, '2026-07-28 10:00:00'),
(31, 3, 'Bình Ủ Lạnh Cold Brew Thủy Tinh 1L', 'binh-u-lanh-cold-brew-1l', 'Lõi lọc lưới thép siêu mịn tháo rời, dễ vệ sinh và vừa cánh cửa tủ lạnh.', 'Thân bình thủy tinh dày 1.000ml kèm ống lọc inox mắt lưới 300 micron cho nước cốt trong, không cặn bột. Nắp vặn kín khí giúp cà phê không bị ám mùi thực phẩm trong tủ lạnh.\n\nChiều cao 26cm, đường kính đáy 8.8cm, gọn gàng cho việc ủ sẵn cà phê uống trong tuần.', NULL, NULL, 1, 0, '2026-07-11 10:00:00'),
(32, 3, 'Bình Đánh Bọt Sữa Cầm Tay Thủ Công', 'binh-danh-bot-sua-thu-cong', 'Lưới pittông kép tạo lớp bọt sữa mịn trong 30 giây không cần điện.', 'Thân inox 304 hai lớp giúp giữ nhiệt sữa ở mức 60–65°C trong lúc đánh bọt. Chỉ cần đổ 150ml sữa tươi thanh trùng ấm vào bình và đẩy pittông đều tay 25–30 nhịp.\n\nDung tích 400ml, vệ sinh đơn giản dưới vòi nước ấm. Hợp pha cappuccino và latte tại nhà.', NULL, NULL, 1, 0, '2026-08-02 10:00:00'),
(33, 4, 'Cốc Gốm Men Tro Không Quai 220ml', 'coc-gom-men-tro-220ml', 'Gốm vuốt tay Bát Tràng phủ men tro tự nhiên, giữ ấm lâu và đầm tay.', 'Mỗi chiếc cốc được chuốt thủ công nên vân men tro có sắc độ khác nhau nhẹ, bề mặt hơi sần tạo cảm giác cầm chắc tay. Miệng cốc loe nhẹ giúp hương cà phê lan tỏa khi uống.\n\nDung tích 220ml, cao 8.5cm, phù hợp uống pour-over nóng hoặc flat white. An toàn với lò vi sóng và máy rửa chén.', NULL, NULL, 1, 1, '2026-07-25 10:00:00'),
(34, 4, 'Cốc Sứ Có Quai Dáng Bầu 300ml', 'coc-su-co-quai-300ml', 'Thành sứ dày 4mm giữ nhiệt tốt, quai cầm rộng thoải mái 2 ngón tay.', 'Thiết kế dáng bầu tròn đáy giúp xoay trộn crema và sữa mượt mà khi rót latte art. Lớp men láng bên trong hạn chế bám màu cà phê sau thời gian dài sử dụng.\n\nDung tích 300ml, đường kính miệng 9cm. Hai tông màu trầm ấm dễ phối với mọi góc bàn làm việc.', NULL, NULL, 1, 0, '2026-08-13 10:00:00'),
(35, 4, 'Ly Espresso Gốm Kèm Đĩa Lót 90ml', 'ly-espresso-gom-90ml', 'Bộ ly nhỏ 90ml chuyên dùng cho espresso đơn và đôi, lòng ly vát tròn.', 'Thành ly dày giúp ổn định nhiệt độ cốt espresso vốn dễ nguội nhanh. Đáy trong bo cong hỗ trợ giữ nguyên lớp crema vàng nâu khi chiết xuất trực tiếp từ máy.\n\nGồm 1 ly 90ml và 1 đĩa lót đồng bộ đường kính 11.5cm, men lì chống trầy xước khi đặt muỗng.', NULL, NULL, 1, 0, '2026-08-10 10:00:00'),
(36, 4, 'Ly Thủy Tinh Hai Lớp 250ml', 'ly-thuy-tinh-hai-lop-250ml', 'Thủy tinh borosilicate 2 lớp cách nhiệt, không đọng sương khi uống đá.', 'Lớp chân không ở giữa giữ cà phê nóng lâu mà bên ngoài cầm không bị bỏng tay; khi pha đồ uống đá mặt ngoài vẫn khô ráo không làm ướt bàn làm việc.\n\nDung tích 250ml, trọng lượng nhẹ 140g. Nên rửa bằng tay với mút mềm để giữ độ trong suốt.', NULL, NULL, 1, 0, '2026-06-30 10:00:00'),
(37, 4, 'Ly Cold Brew Thủy Tinh Gân Sọc 380ml', 'ly-cold-brew-gan-soc-380ml', 'Thân ly sọc dọc cầm chắc tay, dáng cao vừa vặn đá viên và lát cam sấy.', 'Chất liệu thủy tinh trong suốt dày dặn, phần đáy nặng tạo cảm giác vững chãi. Miệng ly rộng 8cm dễ cho đá viên lớn và vệ sinh sạch sẽ.\n\nDung tích 380ml thích hợp cho cà phê ủ lạnh, bạc xỉu, americano đá hoặc trà trái cây.', NULL, NULL, 1, 0, '2026-07-05 10:00:00'),
(38, 4, 'Ly Thử Hương Cảm Quan 200ml', 'ly-thu-huong-cam-quan-200ml', 'Miệng ly thu hẹp rồi loe nhẹ kiểu ly vang, gom hương thơm cà phê lọc.', 'Thiết kế lấy cảm hứng từ ly nếm chuyên nghiệp giúp tập trung các tầng hương hoa và trái cây ở khoang trên, đồng thời làm nguội cà phê đều để vị ngọt bộc lộ rõ hơn.\n\nThủy tinh mỏng 1.5mm, dung tích 200ml, nặng chỉ 95g.', NULL, NULL, 1, 0, '2026-07-04 10:00:00'),
(39, 4, 'Bình Giữ Nhiệt Du Lịch Lõi Sứ 360ml', 'binh-giu-nhiet-loi-su-360ml', 'Lõi tráng men gốm không làm đổi mùi cà phê, giữ nóng 6 giờ và lạnh 10 giờ.', 'Khắc phục nhược điểm có mùi kim loại của bình inox thông thường, lớp phủ gốm bên trong giữ trọn hương thơm nguyên bản của cà phê rang mộc. Nắp bật chống tràn có khóa an toàn.\n\nDung tích 360ml vừa khay đựng ly ô tô và ngăn bên ba lô. Đáy có đệm silicone giảm tiếng ồn khi đặt xuống bàn.', NULL, NULL, 1, 0, '2026-06-18 10:00:00'),
(40, 4, 'Chén Cupping Sứ Trắng 200ml', 'chen-cupping-su-trang-200ml', 'Chén thử nếm tiêu chuẩn đường kính 9cm, thành dày giữ nhiệt đều.', 'Dùng để nếm so sánh nhiều mẻ cà phê cùng lúc theo quy chuẩn cupping. Lòng chén trắng tinh giúp quan sát màu nước và lớp váng cà phê rõ ràng.\n\nDung tích 200ml, có thể xếp chồng gọn gàng khi cất giữ.', NULL, NULL, 1, 0, '2026-08-04 10:00:00'),
(41, 5, 'Giấy Lọc V60 Cỡ 02 (Hộp 100 Tờ)', 'giay-loc-v60-02-100-to', 'Giấy lọc tẩy trắng oxy không mùi giấy, tốc độ chảy ổn định.', 'Sản xuất từ bột gỗ nguyên sinh không dùng clo, không để lại vị giấy khi tráng sơ bằng nước nóng trước khi pha. Độ dày vừa phải giúp lọc sạch dầu thừa cho tách cà phê trong trẻo.\n\nQuy cách 100 tờ/túi, tương thích mọi phễu lọc hình nón cỡ 02 (1–4 tách).', NULL, NULL, 1, 0, '2026-08-06 10:00:00'),
(42, 5, 'Giấy Lọc Đáy Phẳng Cỡ 185 (100 Tờ)', 'giay-loc-day-phang-185', 'Giấy gấp sóng giữ phom chắc chắn, phù hợp phễu Kalita và phễu đáy phẳng.', 'Các nếp gấp sóng đều giúp giữ khoảng trống không khí giữa giấy và thành phễu, hạn chế tắc nghẽn dòng nước khi xay mịn. Không mùi lạ sau khi tráng nước nóng.\n\nĐóng gói 100 tờ trong hộp giấy cứng bảo vệ phom sóng không bị bẹp.', NULL, NULL, 1, 0, '2026-07-05 10:00:00'),
(43, 5, 'Máy Xay Tay Lưỡi Thép CNC 38mm', 'may-xay-tay-cnc-38mm', 'Lưỡi xay thép không gỉ 5 cánh đồng đều, 36 nấc chỉnh từ Espresso tới Cold Brew.', 'Trục đôi vòng bi giúp lưỡi xay không bị rung lắc, giảm tối đa bột mịn dư gây đắng. Thân hợp kim nhôm tiện rãnh chống trượt, sức chứa 25g hạt mỗi lần xay.\n\nChỉnh cỡ xay bằng vòng xoay có tiếng click rõ ràng. Kèm chổi vệ sinh lông mềm và túi vải rút mang theo du lịch.', NULL, NULL, 1, 1, '2026-08-02 10:00:00'),
(44, 5, 'Hộp Bảo Quản Hạt Kín Khí 500g', 'hop-bao-quan-hat-kin-khi-500g', 'Thân thép sơn tĩnh điện tích hợp van thoát khí CO2 một chiều và vòng nhớ ngày.', 'Cà phê mới rang tiếp tục nhả khí CO2; van một chiều trên nắp đẩy khí dư ra ngoài đồng thời ngăn không khí và hơi ẩm xâm nhập. Vòng xoay ngày tháng giúp theo dõi độ tươi của mẻ rang.\n\nChứa được khoảng 450–500g cà phê nguyên hạt, đi kèm muỗng đong thép gắn nam châm bên thân hộp.', NULL, NULL, 1, 0, '2026-07-24 10:00:00'),
(45, 5, 'Nhiệt Kế Cắm Nắp Ấm Rót', 'nhiet-ke-cam-nap-am', 'Mặt đồng hồ cơ inox đo nhanh từ 0°C đến 100°C, không cần pin.', 'Đầu dò dài 13cm bằng inox 304 dễ dàng cắm qua lỗ thông hơi trên nắp ấm cổ ngỗng hoặc kẹp vào ca đánh sữa. Mặt hiển thị rõ vùng nhiệt 88–94°C lý tưởng cho pha cà phê.\n\nCó kẹp gài tháo rời, chống nước bắn khi vệ sinh.', NULL, NULL, 1, 0, '2026-08-08 10:00:00'),
(46, 5, 'Bộ Chổi Vệ Sinh Máy Xay & Khăn Barista', 'bo-choi-ve-sinh-khan-barista', 'Chổi cán gỗ óc chó lông tự nhiên kết hợp 2 khăn sợi nhỏ thấm hút nhanh.', 'Lông chổi cứng vừa phải dễ quét sạch bột cà phê bám trong lưỡi máy xay tay và kẽ phin mà không làm trầy kim loại. Hai khăn microfiber màu nâu tối hạn chế lộ vết cà phê.\n\nKích thước khăn 30x30cm, giặt máy thoải mái và nhanh khô.', NULL, NULL, 1, 0, '2026-07-05 10:00:00'),
(47, 6, 'Hộp Quà Thử Vị 4 Vùng Cà Phê Việt', 'hop-qua-thu-vi-4-vung', '4 túi 100g gồm Cầu Đất, Buôn Ma Thuột, Khe Sanh, Sơn La kèm sổ tay hướng dẫn.', 'Hộp giấy kraft cứng ép kim tên Nhà Rang, bên trong có 4 túi hạt rang mới 100g đại diện 4 vùng trồng tiêu biểu của Việt Nam. Kèm tập hướng dẫn pha cơ bản và thiệp trống để bạn tự viết lời chúc.\n\nBạn có thể chọn nguyên hạt hoặc xay sẵn theo nhu cầu của người nhận.', 'Đà Lạt · Đắk Lắk · Quảng Trị · Sơn La', 'medium', 1, 1, '2026-07-19 10:00:00'),
(48, 6, 'Combo Pha Phin Cho Người Mới', 'combo-pha-phin-nguoi-moi', 'Gồm 1 phin inox 304, 1 túi Blend Phin 250g xay sẵn và 1 ly thủy tinh 380ml.', 'Bộ khởi đầu gọn gàng cho người muốn tự pha ly cà phê sữa đá buổi sáng tại nhà. Toàn bộ dụng cụ đã được chọn khớp kích thước miệng ly để đặt phin chắc chắn.\n\nTiết kiệm 15% so với mua lẻ từng món, kèm thẻ công thức pha phin nóng và phin đá chi tiết.', 'Buôn Ma Thuột & Lâm Đồng', 'dark', 1, 0, '2026-07-12 10:00:00'),
(49, 6, 'Combo Pour-Over V60 Tại Nhà', 'combo-pour-over-v60', 'Trọn bộ phễu gốm V60, bình server 600ml, 100 tờ giấy lọc và 250g Arabica Cầu Đất.', 'Đầy đủ các món cốt lõi để bắt đầu pha cà phê giấy lọc chuẩn vị mà không phải tìm mua lẻ từng phụ kiện tương thích. Hạt Arabica Cầu Đất rang sáng vừa được đóng gói ngay trong tuần.\n\nPhù hợp làm quà tân gia, sinh nhật hoặc tự thưởng cho góc bàn làm việc tại nhà.', 'Cầu Đất, Đà Lạt · 1.550m', 'light', 1, 1, '2026-07-19 10:00:00'),
(50, 6, 'Hộp Quà Văn Phòng Drip & Cốc Gốm', 'hop-qua-van-phong-drip-coc', '1 hộp 10 gói Drip Cầu Đất cùng 1 cốc gốm men tro 220ml trong hộp nắp nam châm.', 'Món quà thực tế cho đồng nghiệp hoặc khách hàng bận rộn: chỉ cần bình nước nóng văn phòng là có ngay tách cà phê rang mộc đựng trong chiếc cốc gốm thủ công ấm tay.\n\nHộp lót mút cắt định hình chống va đập, an toàn khi gửi chuyển phát nhanh toàn quốc.', 'Cầu Đất, Đà Lạt', 'medium', 1, 0, '2026-08-06 10:00:00');
