INSERT INTO reviews (id, product_id, customer_id, rating, title, content, created_at) VALUES
(1, 41, 30, 5, 'Hộp quà chỉn chu, tặng rất ưng', 'Mua tặng sinh nhật sếp, hộp kraft cứng cáp kèm sổ hướng dẫn pha nên người mới cũng dùng được ngay.', '2026-11-10 20:52:00'),
(2, 9, 16, 4, 'Hòa tan nhưng không bị mùi khét', 'Pha nước lạnh tan nhanh, uống giống americano loãng nhẹ, rất hợp những hôm vội không kịp pha phin.', '2026-11-02 04:12:00'),
(3, 40, 22, 5, 'Hộp quà chỉn chu, tặng rất ưng', 'Mua tặng sinh nhật sếp, hộp kraft cứng cáp kèm sổ hướng dẫn pha nên người mới cũng dùng được ngay.', '2026-09-18 06:01:00'),
(4, 9, 62, 4, 'Vị cân bằng, đóng gói kỹ', 'Hạt đều màu, ít hạt vỡ. Cá nhân mình thích chua hơn một chút nhưng tổng thể rất dễ uống hàng ngày.', '2026-09-15 18:50:00'),
(5, 43, 12, 4, 'Bình ủ lạnh lọc sạch bã', 'Ống lọc tháo rửa dễ, bỏ vừa cánh cửa tủ lạnh. Ủ một bình uống được 3 ngày.', '2026-11-20 17:26:00'),
(6, 10, 14, 2, 'Giao hơi lâu một chút', 'Cà phê uống ổn nhưng đơn này bên vận chuyển giữ hàng hơi lâu nên nhận trễ 2 ngày.', '2026-11-19 13:34:00'),
(7, 23, 49, 4, 'Tiện mang đi du lịch', 'Xếp gọn hết vào cốc luôn, mang đi cắm trại pha được cà phê nóng uống sáng rất thích.', '2026-10-03 05:57:00'),
(8, 19, 12, 5, 'Hương thơm rõ, hạt rang rất mới', 'Mở túi ra thơm nức mùi hạt rang mộc, pha V60 lên đúng vị cam và hậu ngọt nhẹ. Ngày rang in trên bao mới cách lúc nhận 3 ngày.', '2026-11-18 17:26:00'),
(9, 42, 53, 4, 'Phin inox dày dặn', 'Lỗ lọc đều nên cà phê nhỏ giọt chậm vừa phải, khoảng 5 phút là xong một ly đậm.', '2026-09-28 07:30:00'),
(10, 4, 22, 5, 'Crema dày, hậu vị ngọt lâu', 'Chạy máy espresso ở nhà chiết xuất đẹp, crema màu cánh gián dày mịn. Pha latte sáng uống rất cuốn.', '2026-10-28 02:43:00'),
(11, 32, 23, 5, 'Gốm cầm đầm tay, men rất đẹp', 'Màu men bên ngoài trầm ấm hơn cả ảnh chụp, giữ nhiệt tốt. Rửa xong không bị bám ố màu cà phê.', '2026-11-12 16:11:00'),
(12, 34, 24, 4, 'Hoàn thiện tốt trong tầm giá', 'Phễu lọc vừa khít bình server, rãnh xoắn thoát nước đều. Hộp đóng gói có lớp chống sốc dày.', '2026-09-03 05:31:00'),
(13, 43, 45, 5, 'Máy xay chạy êm, bột đều', 'Lưỡi thép CNC xay 18g hạt chỉ mất khoảng 35 giây, ít bụi mịn hơn hẳn cái máy cũ mình dùng.', '2026-11-01 18:32:00'),
(14, 12, 38, 2, 'Giao hơi lâu một chút', 'Cà phê uống ổn nhưng đơn này bên vận chuyển giữ hàng hơi lâu nên nhận trễ 2 ngày.', '2026-08-31 23:06:00'),
(15, 23, 34, 4, 'Bình ủ lạnh lọc sạch bã', 'Ống lọc tháo rửa dễ, bỏ vừa cánh cửa tủ lạnh. Ủ một bình uống được 3 ngày.', '2026-09-12 22:27:00'),
(16, 4, 29, 5, 'Uống nóng hay đá đều hợp', 'Thử pha giấy lọc tỉ lệ 1:15 theo gợi ý trên web, nước trong, vị chua thanh dễ chịu. Sẽ mua lại túi 500g.', '2026-09-07 04:45:00'),
(17, 37, 62, 3, 'Kích thước hơi nhỏ hơn tưởng tượng', 'Dùng pha 1–2 ly thì vừa đẹp, nhưng nếu nhà đông người chắc nên chọn cỡ lớn hơn.', '2026-10-29 08:11:00'),
(18, 22, 52, 4, 'Bình ủ lạnh lọc sạch bã', 'Ống lọc tháo rửa dễ, bỏ vừa cánh cửa tủ lạnh. Ủ một bình uống được 3 ngày.', '2026-10-29 00:42:00'),
(19, 1, 32, 5, 'Pha Aeropress ra vị rất sạch', 'Hương hoa quả mở rõ khi cà phê nguội bớt. Đáng tiền cho một mẻ rang nhỏ trong nước.', '2026-09-26 21:08:00'),
(20, 29, 53, 4, 'Phin inox dày dặn', 'Lỗ lọc đều nên cà phê nhỏ giọt chậm vừa phải, khoảng 5 phút là xong một ly đậm.', '2026-09-30 07:30:00'),
(21, 43, 52, 4, 'Tiện mang đi du lịch', 'Xếp gọn hết vào cốc luôn, mang đi cắm trại pha được cà phê nóng uống sáng rất thích.', '2026-09-26 03:10:00'),
