(37, 16, 45, 4, 'Hòa tan nhưng không bị mùi khét', 'Pha nước lạnh tan nhanh, uống giống americano loãng nhẹ, rất hợp những hôm vội không kịp pha phin.', '2026-11-23 03:00:00'),
(38, 6, 29, 4, 'Hạt đẹp, hương vị ổn định', 'Mua lần thứ hai rồi, chất lượng giữa các mẻ khá đồng đều. Túi có khóa zip và van một chiều bảo quản tiện.', '2026-10-08 01:14:00'),
(39, 23, 47, 5, 'Combo tiết kiệm, đủ món cần dùng', 'Mua bộ V60 này về là pha được luôn không phải mò mẫm chọn từng món cho khớp kích cỡ.', '2026-10-20 14:46:00'),
(40, 32, 32, 5, 'Rót nước mượt, dễ kiểm soát dòng', 'Vòi cổ ngỗng mảnh nên mới tập pha V60 vẫn rót đều tay được. Lớp sơn đen nhám nhìn rất gọn.', '2026-09-22 21:08:00'),
